// The bundled example datasets are described by public/examples/manifest.json, generated by
// scripts/sync-examples.ts. This module is the single definition of that format, shared by the
// generator, the app (which fetches and validates it) and the tests.

export const MANIFEST_VERSION = 1;

export interface ExampleFile {
  /** Path relative to the group directory (`public/examples/<id>/`). */
  path: string;
  bytes: number;
}

export interface ExampleDataset {
  /** Path of the table root schema within the group. */
  root: string;
  title: string;
  variables: number;
  categories: number;
}

export interface ExampleGroup {
  /** Directory name under public/examples/ and the batch label prefix (kebab-case). */
  id: string;
  /** Short label shown on chips and cards (e.g. "BGS"). */
  label: string;
  /** Human name of the schema set. */
  name: string;
  /** One-line description. */
  description: string;
  /** Path of the set inside the upstream repository. */
  sourcePath: string;
  bytes: number;
  files: ExampleFile[];
  /** Tables the library finds in the set (informational: the app re-detects roots when loading). */
  datasets: ExampleDataset[];
}

export interface ExampleManifest {
  $comment?: string;
  version: typeof MANIFEST_VERSION;
  source: {
    name: string;
    url: string;
    license: string;
    copyright: string;
    licenseFile: string;
  };
  groups: ExampleGroup[];
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isString(value: unknown): value is string {
  return typeof value === "string";
}

function isCount(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) && value >= 0;
}

/** Structural validation of a parsed manifest (a fetched file is untrusted input). */
export function isExampleManifest(value: unknown): value is ExampleManifest {
  if (!isRecord(value) || value.version !== MANIFEST_VERSION) return false;
  const source = value.source;
  if (
    !isRecord(source) ||
    !isString(source.name) ||
    !isString(source.url) ||
    !isString(source.license) ||
    !isString(source.copyright) ||
    !isString(source.licenseFile)
  ) {
    return false;
  }
  if (!Array.isArray(value.groups) || value.groups.length === 0) return false;
  return value.groups.every(
    (group: unknown) =>
      isRecord(group) &&
      isString(group.id) &&
      /^[a-z0-9-]+$/.test(group.id) &&
      isString(group.label) &&
      isString(group.name) &&
      isString(group.description) &&
      isString(group.sourcePath) &&
      isCount(group.bytes) &&
      Array.isArray(group.files) &&
      group.files.length > 0 &&
      group.files.every(
        (file: unknown) =>
          isRecord(file) &&
          isString(file.path) &&
          /^[^/\s][^\s]*\.json$/.test(file.path) &&
          isCount(file.bytes)
      ) &&
      Array.isArray(group.datasets) &&
      group.datasets.every(
        (dataset: unknown) =>
          isRecord(dataset) &&
          isString(dataset.root) &&
          isString(dataset.title) &&
          isCount(dataset.variables) &&
          isCount(dataset.categories)
      )
  );
}
